<script setup>import { computed } from 'vue';const props=defineProps({label:String,value:Number,left:String,right:String,invert:Boolean});const score=computed(()=>Math.max(0,Math.min(100,props.invert?100-Number(props.value||0):Number(props.value||0))));const ordinal=computed(()=>{const value=Math.round(score.value),mod100=value%100;if(mod100>=11&&mod100<=13)return`${value}th`;return`${value}${value%10===1?'st':value%10===2?'nd':value%10===3?'rd':'th'}`})</script>
<template><div class="percentile"><header><span>{{label}}</span><b>{{ordinal}}</b></header><div><i :style="{width:`${score}%`}"></i><em></em></div><footer><span>{{left||'LOW'}}</span><span>LEAGUE MEDIAN</span><span>{{right||'HIGH'}}</span></footer></div></template>
<style scoped>.percentile{display:grid;gap:7px}.percentile header,.percentile footer{display:flex;justify-content:space-between;align-items:center}.percentile header span{font-size:11px}.percentile header b{font:800 10px 'DM Mono';color:var(--sport,var(--accent))}.percentile>div{height:7px;position:relative;background:var(--line)}.percentile>div i{position:absolute;inset:0 auto 0 0;background:linear-gradient(90deg,var(--blue),var(--sport,var(--accent)));transition:width .6s cubic-bezier(.22,.8,.3,1)}.percentile>div em{position:absolute;left:50%;top:-3px;width:1px;height:13px;background:var(--text);opacity:.5}.percentile footer{font:600 6px 'DM Mono';color:var(--muted)}</style>
